#!/bin/bash
# Usage: return <device>. Removes the device's loan from $LOANS.
root=$(cd "$(dirname "$0")/.." && pwd)
loans=${LOANS:-$root/data/loans.tsv}
awk -F'\t' -v d="$1" '$1 != d' "$loans" > "$loans.tmp" && mv "$loans.tmp" "$loans"
echo "returned $1"

